              return SinglePartitionPublisherBuilder.newBuilder()
                  .setTopic(topic)
                  .setPartition(partition)
                  .setContext(PubsubContext.of(FRAMEWORK))
                  .build();
            } catch (Exception e) {
              throw new RuntimeException(e);
            }
          }

          @Override
          public void close() {}
        });
    return builder.build();
  }
}

