    36→
    37→  @Override
    38→  public Publisher<MessageMetadata> newPublisher(Map<String, String> params) {
    39→    Map<String, ConfigValue> config = ConfigDefs.config().validateAll(params);
    40→    RoutingPublisherBuilder.Builder builder = RoutingPublisherBuilder.newBuilder();
    41→    TopicPath topic =
    42→        TopicPath.newBuilder()
    43→            .setProject(
    44→                ProjectPath.parse("projects/" + config.get(ConfigDefs.PROJECT_FLAG).value())
    45→                    .project())
    46→            .setLocation(CloudZone.parse(config.get(ConfigDefs.LOCATION_FLAG).value().toString()))
    47→            .setName(TopicName.of(config.get(ConfigDefs.TOPIC_NAME_FLAG).value().toString()))
    48→            .build();
    49→    builder.setTopic(topic);
    50→    builder.setPublisherFactory(
    51→        new PartitionPublisherFactory() {
    52→          @Override
