package com.google.pubsublite.kafka.sink;

import com.google.api.gax.batching.BatchingSettings;
import com.google.api.gax.batching.FlowControlSettings;
import com.google.api.gax.rpc.ApiException;
import com.google.api.gax.rpc.ClientStream;
import com.google.api.gax.rpc.ResponseObserver;
import com.google.cloud.pubsublite.CloudZone;
import com.google.cloud.pubsublite.MessageMetadata;
import com.google.cloud.pubsublite.Partition;
import com.google.cloud.pubsublite.ProjectPath;
import com.google.cloud.pubsublite.TopicName;
import com.google.cloud.pubsublite.TopicPath;
import com.google.cloud.pubsublite.internal.Publisher;
import com.google.cloud.pubsublite.internal.wire.PartitionPublisherFactory;
import com.google.cloud.pubsublite.internal.wire.PubsubContext;
import com.google.cloud.pubsublite.internal.wire.PubsubContext.Framework;
import com.google.cloud.pubsublite.internal.wire.RoutingPublisherBuilder;
import com.google.cloud.pubsublite.internal.wire.SinglePartitionPublisherBuilder;
import com.google.cloud.pubsublite.internal.wire.StreamFactories.PublishStreamFactory;
import com.google.cloud.pubsublite.proto.PublishRequest;
import com.google.cloud.pubsublite.proto.PublishResponse;
import com.google.cloud.pubsublite.v1.PublisherServiceClient;
import com.google.cloud.pubsublite.v1.PublisherServiceSettings;
import java.io.IOException;
import java.util.Map;
import org.apache.kafka.common.config.ConfigValue;

class PublisherFactoryImpl implements PublisherFactory {

  private static final Framework FRAMEWORK = Framework.of("KAFKA_CONNECT");
  private static final BatchingSettings BATCHING_SETTINGS =
      BatchingSettings.newBuilder()
          .setIsEnabled(true)
          .setElementCountThreshold(1000L)
          .setRequestByteThreshold(3670016L)
          .setFlowControlSettings(
              FlowControlSettings.newBuilder()
                  .setMaxOutstandingRequestBytes(32L * 1024L * 1024L)
                  .build())
          .build();

  @Override
  public Publisher<MessageMetadata> newPublisher(Map<String, String> params) {
    Map<String, ConfigValue> config = ConfigDefs.config().validateAll(params);
    RoutingPublisherBuilder.Builder builder = RoutingPublisherBuilder.newBuilder();
    TopicPath topic =
        TopicPath.newBuilder()
            .setProject(
                ProjectPath.parse("projects/" + config.get(ConfigDefs.PROJECT_FLAG).value())
                    .project())
            .setLocation(CloudZone.parse(config.get(ConfigDefs.LOCATION_FLAG).value().toString()))
            .setName(TopicName.of(config.get(ConfigDefs.TOPIC_NAME_FLAG).value().toString()))
            .build();
    builder.setTopic(topic);
    builder.setPublisherFactory(
        new PartitionPublisherFactory() {
          @Override
          public Publisher<MessageMetadata> newPublisher(Partition partition) {
            try {
              PublisherServiceSettings clientSettings =
                  PublisherServiceSettings.newBuilder()
                      .setCredentialsProvider(PubsubContext.of(FRAMEWORK)::getMetadata)
                      .build();
              PublisherServiceClient client = PublisherServiceClient.create(clientSettings);
              return SinglePartitionPublisherBuilder.newBuilder()
                  .setTopic(topic)
                  .setPartition(partition)
                  .setBatchingSettings(BATCHING_SETTINGS)
                  .setStreamFactory(
                      (ResponseObserver<PublishResponse> observer) ->
                          client.publishPartitionStreamBuilder()
                              .setPartition(topic.toSubscriptionPath().toString())
                              .setResponseObserver(observer)
                              .build())
                  .build();
            } catch (IOException e) {
              throw new RuntimeException(e);
            }
          }

          @Override
          public void close() {}
        });
    return builder.build();
  }
}

